typedef unsigned int u_int;
typedef unsigned char u_char;
typedef unsigned long u_long;
typedef char* va_list;
#define va_start(ap, last) (ap = (char*)__builtin_next_arg())
#define va_end(ap) ((void)0)
#define NULL 0

struct nglFont;
struct nglStringNode
{
  char* Text;
  nglFont* Font;
  float X, Y, Z;
  u_int Color;
};

typedef void (*nglCustomNodeFn)( u_int*& Packet, void* Data );
struct nglSortInfo
{
  u_int Type;
  union {
    float Dist;
    u_int Hash;
  };
};

enum { NGLSORT_TRANSLUCENT };
enum { NGLNODE_STRING = 3 };

extern char nglWork[];
void* nglListAlloc( u_int Size );
int vsprintf( char* Buffer, const char* Format, va_list Args );
u_int strlen( const char* Text );
void* memcpy( void* Dest, const void* Source, u_int Size );
void nglVif1RenderString( u_int*& Packet, void* Param );
void nglListAddNode( u_int Type, nglCustomNodeFn NodeFn, void* Data, nglSortInfo* SortInfo, u_char** Buf = NULL );
#define nglListNew( Type ) (Type*)nglListAlloc( sizeof(Type) )

void nglListAddString( nglFont* Font, float x, float y, double z, u_int Color, const char* Text, ... )
{
  if (Text == NULL || *Text == '\0' || Font == NULL )
    return;

  nglStringNode* StringNode = nglListNew( nglStringNode );
  if ( !StringNode )
    return;

  va_list argptr;
  va_start( argptr, Text );
  vsprintf( nglWork, Text, argptr );
  va_end( argptr );

  u_int Len = strlen( nglWork );
  StringNode->Text = (char*)nglListAlloc( Len + 1 );
  memcpy( StringNode->Text, nglWork, Len + 1 );

  StringNode->Font = Font;
  StringNode->Color = Color;
  StringNode->X = x;
  StringNode->Y = y;
  StringNode->Z = z;

  nglSortInfo SortInfo;
  SortInfo.Type = NGLSORT_TRANSLUCENT;
  SortInfo.Dist = z;
  nglListAddNode( NGLNODE_STRING, nglVif1RenderString, StringNode, &SortInfo );
}
